from collections import deque

dist = {start: 0}
queue = deque([start])
while queue:
    node = queue.popleft()
    for nxt in neighbors(node):
        if nxt not in dist:
            dist[nxt] = dist[node] + 1
            queue.append(nxt)

intervals.sort()  # by start
merged = []
for start, end in intervals:
    if merged and start <= merged[-1][1]:
        merged[-1][1] = max(merged[-1][1], end)
    else:
        merged.append([start, end])

lo, hi = smallest_possible, largest_possible
while lo < hi:
    mid = (lo + hi) // 2
    if feasible(mid):
        hi = mid      # mid works, try smaller
    else:
        lo = mid + 1
return lo

parent = list(range(n))
def find(x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]  # path halving
        x = parent[x]
    return x
def union(a, b):
    ra, rb = find(a), find(b)
    if ra == rb:
        return False
    parent[ra] = rb
    return True

stack = []
for x in items:
    while stack and conflicts(stack[-1], x):
        resolve(stack.pop(), x)
    if still_alive(x):
        stack.append(x)

def dfs(node):
    if not node:
        return base
    left = dfs(node.left)
    right = dfs(node.right)
    # combine children, update a global answer if needed
    return combine(node, left, right)

def backtrack(path, start):
    if done(path):
        out.append(path[:])
        return
    for i in range(start, n):
        path.append(choice(i))
        backtrack(path, i + 1)
        path.pop()  # undo

out = []
for i, ch in enumerate(s):
    # apply the rule for this step
    out.append(transform(ch))
return ''.join(out)
